const kot = {
  imie: "Filemon",
  miauknij() {
    console.log(`${this.imie} mowi: Miau!`);
  },
};

const samodzielnaFunkcja = kot.miauknij;
samodzielnaFunkcja();
// "undefined mowi: Miau!" - this zgubil powiazanie z kot, bo funkcja
// zostala wywolana samodzielnie, bez kropki poprzedzonej obiektem kot.

function wykonaj(fn) {
  console.log(fn());
}

const sklep = {
  nazwa: "Kwiaciarnia u Ani",
  podajNazwe() {
    return this.nazwa;
  },
};

wykonaj(sklep.podajNazwe);
// undefined - this gubi sie, bo funkcja wykonaj przyjmuje jedynie SAMA
// funkcje podajNazwe jako argument fn, bez zadnej informacji o tym, ze
// pierwotnie byla zwiazana z obiektem sklep. Wywolanie fn() wewnatrz
// wykonaj jest wywolaniem SAMODZIELNYM, bez kropki i obiektu przed nia.

const uzytkownik = { imie: "Kasia", pokazImie() { return this.imie; } };
const luznaFunkcja = uzytkownik.pokazImie;

console.log(uzytkownik.pokazImie()); // "Kasia" - wywolanie PRZEZ obiekt, this dziala
console.log(luznaFunkcja());          // undefined - wywolanie SAMODZIELNE, this zgubiony
// Ta sama funkcja daje rozne wyniki w zaleznosci wylacznie od SPOSOBU wywolania.

const panel = {
  widoczny: false,
  przelacz() {
    this.widoczny = !this.widoczny;
  },
};

setTimeout(panel.przelacz, 100);
// setTimeout wywoluje przekazana funkcje SAMODZIELNIE (bez kropki i bez
// obiektu panel przed nia) - this wewnatrz przelacz bedzie undefined,
// wiec this.widoczny = !this.widoczny rzuci blad probujac odczytac
// wlasciwosc widoczny z undefined.

const formularz = { dane: {}, zapisz(klucz, wartosc) { this.dane[klucz] = wartosc; } };
const zapiszWyciagniete = formularz.zapisz;

// zapiszWyciagniete("email", "test@test.pl");
// Blad: Cannot set properties of undefined (setting 'email')
// this jest undefined (funkcja wywolana samodzielnie), wiec proba
// this.dane['email'] = ... to proba odczytu wlasciwosci dane z undefined.

const uzytkownik = { imie: "Ola", pokazImie() { return this.imie; } };
const { pokazImie } = uzytkownik;

console.log(pokazImie()); // undefined
// Destrukturyzacja, mimo ze wyglada na proste "pobranie pola", technicznie
// wykonuje DOKLADNIE to samo, co przypisanie metody do osobnej zmiennej -
// kopiuje SAMA funkcje, bez informacji o obiekcie uzytkownik. Wywolanie
// pokazImie() jest wiec wywolaniem samodzielnym, this jest undefined.

const gra = { wynik: 0, dodajPunkt() { this.wynik++; } };
const funkcje = [gra.dodajPunkt, gra.dodajPunkt];

// funkcje.forEach(f => f()); -- rzuci blad (this undefined)
console.log(gra.wynik); // 0
// Kazdy element tablicy funkcje to wyciagnieta, samodzielna funkcja -
// zadna z nich nie "wie", ze pochodzi z obiektu gra, wiec this wewnatrz
// kazdej z nich jest undefined, a gra.wynik nigdy nie zostaje zwiekszony.

// Metoda TRACI powiazanie z this (staje sie "gola" funkcja) w trzech
// sytuacjach:
// 1. Przypisanie do zmiennej: const fn = obiekt.metoda;
// 2. Przekazanie jako argument: funkcja(obiekt.metoda), setTimeout(obiekt.metoda, ...)
// 3. Destrukturyzacja: const { metoda } = obiekt;
//
// Metoda ZACHOWUJE powiazanie z this TYLKO gdy jest wywolywana BEZPOSREDNIO
// przez oryginalny obiekt, z kropka tuz przed wywolaniem:
// obiekt.metoda() -- dziala zawsze poprawnie, this === obiekt

"use strict";

const kot = {
  imie: "Filemon",
  powiedz() {
    return this.imie;
  }
};

const luzna = kot.powiedz;
console.log(kot.powiedz()); // -> "Filemon"
try {
  console.log(luzna());
} catch (e) {
  console.log(e.name);      // -> "TypeError"
}

"use strict";

const licznik = {
  wartosc: 0,
  zwieksz() {
    this.wartosc++;
  }
};

function wykonajDwa(fn) {
  fn();
  fn();
}

try {
  wykonajDwa(licznik.zwieksz);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

wykonajDwa(() => licznik.zwieksz());
console.log(licznik.wartosc); // -> 2

"use strict";

const uzytkownik = {
  lista: [],
  dodaj(x) {
    this.lista.push(x);
  }
};

try {
  [1, 2, 3].forEach(uzytkownik.dodaj);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

[1, 2, 3].forEach(x => uzytkownik.dodaj(x));
console.log(uzytkownik.lista); // -> [1, 2, 3]

"use strict";

const osoba = {
  imie: "Ola",
  pokaz() {
    return this.imie;
  }
};

const { imie, pokaz } = osoba;
console.log(imie); // -> "Ola" (zwykla wartosc tekstowa)
try {
  console.log(pokaz());
} catch (e) {
  console.log(e.name); // -> "TypeError"
}
// Pole zostalo skopiowane jako wartosc, a metoda - jako "goła" funkcja bez obiektu.

"use strict";

const mnoznik = {
  wspolczynnik: 2,
  podwoj(n) {
    return n * this.wspolczynnik;
  }
};

try {
  [1, 2, 3].map(mnoznik.podwoj);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

console.log([1, 2, 3].map(n => mnoznik.podwoj(n))); // -> [2, 4, 6]

const a = { imie: "A", pokaz() { return this.imie; } };
const b = { imie: "B" };

const f = a.pokaz;
b.pokaz = f;

console.log(b.pokaz()); // -> "B"
console.log(a.pokaz()); // -> "A"
// Ta sama funkcja, ale wywolanie "na b" daje this rowne b.

"use strict";

const o = {
  m() {
    return this === undefined;
  }
};

const wyciagnieta = o.m;
console.log(o.m());             // -> false
console.log(wyciagnieta());     // -> true
console.log(o.m === wyciagnieta); // -> true

"use strict";

const logger = {
  prefix: "[LOG]",
  log(tekst) {
    console.log(this.prefix + " " + tekst);
  }
};

try {
  ["a", "b"].forEach(logger.log);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

["a", "b"].forEach(t => logger.log(t));
// -> "[LOG] a"
// -> "[LOG] b"

"use strict";

const o = {
  n: 5,
  zwroc() {
    return function () {
      return this.n;
    };
  }
};

const f = o.zwroc();
try {
  console.log(f());
} catch (e) {
  console.log(e.name); // -> "TypeError"
}
// Zwrocona funkcja jest wywolana samodzielnie (f()), wiec this jest undefined.

"use strict";

const o = {
  imie: "Ala",
  pokaz() {
    return this.imie;
  }
};

console.log(o.pokaz());   // -> "Ala"
console.log((o.pokaz)()); // -> "Ala" (nawiasy nie usuwaja powiazania z obiektem)
try {
  console.log((0, o.pokaz)());
} catch (e) {
  console.log(e.name);    // -> "TypeError" (operator przecinka zwraca sama funkcje)
}

"use strict";

const o = {
  imie: "Ala",
  pozdrow() {
    return "Czesc " + this.imie;
  }
};

try {
  ["a", "b"].map(o.pozdrow);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

console.log(["a", "b"].map(() => o.pozdrow())); // -> ["Czesc Ala", "Czesc Ala"]

function wywolajMetode(obiekt, nazwa) {
  return obiekt[nazwa]();
}

const o = { n: 3, f() { return this.n; } };
console.log(wywolajMetode(o, "f")); // -> 3

"use strict";

function probuj(fn) {
  try {
    fn();
    return "dziala";
  } catch {
    return "blad";
  }
}

const o = { imie: "Ala", pokaz() { return this.imie.length; } };
const wyciagnieta = o.pokaz;
const { pokaz } = o;

console.log(probuj(() => o.pokaz())); // -> "dziala"
console.log(probuj(wyciagnieta));     // -> "blad"
console.log(probuj(pokaz));           // -> "blad"
console.log(probuj(() => pokaz()));   // -> "blad"

"use strict";

const o = {
  n: 5,
  f() {
    const self = this;
    function wewnetrzna() {
      return self.n;
    }
    return wewnetrzna();
  }
};

console.log(o.f()); // -> 5

"use strict";

const o = {
  lista: [],
  zle(t) {
    t.forEach(function (x) {
      this.lista.push(x);
    });
  },
  dobrze(t) {
    t.forEach(function (x) {
      this.lista.push(x);
    }, this);
  }
};

try {
  o.zle([1, 2]);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

o.dobrze([1, 2]);
console.log(o.lista); // -> [1, 2]

"use strict";

const licznik = { n: 0, zwieksz() { this.n++; } };

const przycisk = {
  handlery: [],
  naKlik(fn) {
    this.handlery.push(fn);
  },
  kliknij() {
    this.handlery.forEach(h => h());
  }
};

przycisk.naKlik(licznik.zwieksz);
try {
  przycisk.kliknij();
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

przycisk.handlery = [];
przycisk.naKlik(() => licznik.zwieksz());
przycisk.kliknij();
console.log(licznik.n); // -> 1

function stworzLicznik() {
  let n = 0;
  return {
    zwieksz() {
      n++;
      return n;
    }
  };
}

const { zwieksz } = stworzLicznik();
console.log(zwieksz()); // -> 1
console.log(zwieksz()); // -> 2
// Metoda korzysta ze zmiennej z domkniecia, a nie z this - dlatego wyciagniecie jej nie szkodzi.

const o = {
  stala() {
    return 42;
  }
};

function wykonaj(fn) {
  return fn();
}

const f = o.stala;
console.log(f());          // -> 42
console.log(wykonaj(o.stala)); // -> 42
// Metoda bez this nie zalezy od obiektu - wyciagniecie jej jest bezpieczne.

"use strict";

const firma = {
  dzial: {
    nazwa: "Kadry",
    opis() {
      return this.nazwa;
    }
  }
};

console.log(firma.dzial.opis()); // -> "Kadry"

const { opis } = firma.dzial;
try {
  console.log(opis());
} catch (e) {
  console.log(e.name);           // -> "TypeError"
}

"use strict";

const komparator = {
  kierunek: 1,
  porownaj(a, b) {
    return (a - b) * this.kierunek;
  }
};

try {
  [3, 1, 2].sort(komparator.porownaj);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

console.log([3, 1, 2].sort((a, b) => komparator.porownaj(a, b))); // -> [1, 2, 3]

"use strict";

const filtr = {
  prog: 10,
  czyDuze(n) {
    return n > this.prog;
  }
};

try {
  [5, 15, 25].filter(filtr.czyDuze);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

console.log([5, 15, 25].filter(n => filtr.czyDuze(n))); // -> [15, 25]

"use strict";

const o = { n: 1, m() { return this.n; } };

const przypisana = o.m;                 // 1. przypisanie do zmiennej -> this zgubione
try {
  [1].forEach(o.m);                     // 2. callback -> this zgubione (TypeError, bo metoda uzywa this)
} catch (e) {
  console.log(e.name);                  // -> "TypeError"
}
const { m } = o;                        // 3. destrukturyzacja -> this zgubione
console.log(o.m());                     // 4. wywolanie przez obiekt -> this zachowane (1)

